package com.pvpwhgame.hyperoscharge.ui

import androidx.compose.foundation.Canvas
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material3.*
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.nativeCanvas
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import com.pvpwhgame.hyperoscharge.data.HistoryPoint

@Composable
fun TempThrottleChart(points: List<HistoryPoint>, modifier: Modifier = Modifier) {
    if (points.size < 2) return
    val displayPoints = points.takeLast(300)

    Card(
        modifier = modifier.fillMaxWidth(),
        colors = CardDefaults.cardColors(containerColor = Color(0xFF1A1A20)),
        shape = RoundedCornerShape(14.dp)
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Text("温度 / 限流曲线", fontSize = 14.sp, color = Color(0xFFAAAAAA))
            Spacer(Modifier.height(8.dp))
            Canvas(modifier = Modifier
                .fillMaxWidth()
                .height(150.dp)) {

                val padL = 34f; val padR = 34f; val padT = 8f; val padB = 18f
                val plotW = size.width - padL - padR
                val plotH = size.height - padT - padB

                val t0 = displayPoints.first().ts.toFloat()
                val t1 = displayPoints.last().ts.toFloat()
                val span = (t1 - t0).coerceAtLeast(1f)

                val temps = displayPoints.map { it.tempC }
                val rawMin = temps.min(); val rawMax = temps.max()
                val mid = (rawMax + rawMin) / 2
                val tMin = (mid - 3f).coerceAtMost(rawMin - 0.5f)
                val tMax = (mid + 3f).coerceAtLeast(rawMax + 0.5f)

                val x: (Float) -> Float = { ts -> padL + ((ts - t0) / span) * plotW }
                val yTemp: (Float) -> Float = { t -> padT + plotH - ((t - tMin) / (tMax - tMin)) * plotH }
                val yState: (Float) -> Float = { pct -> padT + plotH - (pct / 100f) * plotH }

                // Grid lines
                for (i in 0..2) {
                    val ty = tMin + (tMax - tMin) * (i / 2f)
                    val yy = yTemp(ty)
                    drawLine(Color(0xFF22222A), Offset(padL, yy), Offset(size.width - padR, yy))
                    drawContext.canvas.nativeCanvas.drawText(
                        String.format("%.0f°", ty), 2f, yy + 4f,
                        android.graphics.Paint().apply {
                            color = 0xFFF4A23D.toInt()
                            textSize = 24f
                        }
                    )
                }

                // Throttle area
                val areaPath = Path().apply {
                    moveTo(x(displayPoints.first().ts.toFloat()), yState(0f))
                    displayPoints.forEach { lineTo(x(it.ts.toFloat()), yState(it.statePercent * 100f)) }
                    lineTo(x(displayPoints.last().ts.toFloat()), yState(0f))
                    close()
                }
                drawPath(areaPath, Color(0x1F5B8DFF))

                // Throttle line
                val throttlePath = Path().apply {
                    displayPoints.forEachIndexed { i, p ->
                        val px = x(p.ts.toFloat()); val py = yState(p.statePercent * 100f)
                        if (i == 0) moveTo(px, py) else lineTo(px, py)
                    }
                }
                drawPath(throttlePath, Color(0xFF5B8DFF), style = Stroke(width = 2f))

                // Temp line
                val tempPath = Path().apply {
                    displayPoints.forEachIndexed { i, p ->
                        val px = x(p.ts.toFloat()); val py = yTemp(p.tempC)
                        if (i == 0) moveTo(px, py) else lineTo(px, py)
                    }
                }
                drawPath(tempPath, Color(0xFFF4A23D), style = Stroke(width = 2.5f))
            }
            Spacer(Modifier.height(8.dp))
            Row(horizontalArrangement = Arrangement.spacedBy(16.dp)) {
                LegendDot(Color(0xFFF4A23D), "温度(°C)")
                LegendDot(Color(0xFF5B8DFF), "限流强度(%)")
            }
        }
    }
}

@Composable
fun PowerChart(points: List<HistoryPoint>, modifier: Modifier = Modifier) {
    if (points.size < 2) return
    val displayPoints = points.takeLast(300)

    Card(
        modifier = modifier.fillMaxWidth(),
        colors = CardDefaults.cardColors(containerColor = Color(0xFF1A1A20)),
        shape = RoundedCornerShape(14.dp)
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Text("功率曲线", fontSize = 14.sp, color = Color(0xFFAAAAAA))
            Spacer(Modifier.height(8.dp))
            Canvas(modifier = Modifier
                .fillMaxWidth()
                .height(140.dp)) {

                val padL = 34f; val padR = 8f; val padT = 8f; val padB = 18f
                val plotW = size.width - padL - padR
                val plotH = size.height - padT - padB

                val t0 = displayPoints.first().ts.toFloat()
                val t1 = displayPoints.last().ts.toFloat()
                val span = (t1 - t0).coerceAtLeast(1f)

                val powers = displayPoints.map { it.powerW }
                val rawPMax = powers.max().coerceAtLeast(0f)
                val pMax = ((rawPMax / 10f).toInt() + 1) * 10f
                val pMaxFinal = pMax.coerceAtLeast(40f)

                val x: (Float) -> Float = { ts -> padL + ((ts - t0) / span) * plotW }
                val yPower: (Float) -> Float = { pw -> padT + plotH - (pw / pMaxFinal) * plotH }

                // Grid
                var pw = 0f
                while (pw <= pMaxFinal) {
                    val yy = yPower(pw)
                    drawLine(Color(0xFF22222A), Offset(padL, yy), Offset(size.width - padR, yy))
                    drawContext.canvas.nativeCanvas.drawText(
                        "${pw.toInt()}W", 2f, yy + 4f,
                        android.graphics.Paint().apply {
                            color = 0xFF4ADE80.toInt()
                            textSize = 24f
                        }
                    )
                    pw += 10f
                }

                // Area
                val areaPath = Path().apply {
                    moveTo(x(displayPoints.first().ts.toFloat()), yPower(0f))
                    displayPoints.forEach { lineTo(x(it.ts.toFloat()), yPower(it.powerW)) }
                    lineTo(x(displayPoints.last().ts.toFloat()), yPower(0f))
                    close()
                }
                drawPath(areaPath, Color(0x1F4ADE80))

                // Line
                val linePath = Path().apply {
                    displayPoints.forEachIndexed { i, p ->
                        val px = x(p.ts.toFloat()); val py = yPower(p.powerW)
                        if (i == 0) moveTo(px, py) else lineTo(px, py)
                    }
                }
                drawPath(linePath, Color(0xFF4ADE80), style = Stroke(width = 2.5f))
            }
            Spacer(Modifier.height(8.dp))
            LegendDot(Color(0xFF4ADE80), "功率(W)")
        }
    }
}

@Composable
private fun LegendDot(color: Color, label: String) {
    Row(verticalAlignment = androidx.compose.ui.Alignment.CenterVertically) {
        Canvas(modifier = Modifier.size(8.dp)) {
            drawCircle(color)
        }
        Spacer(Modifier.width(4.dp))
        Text(label, fontSize = 11.sp, color = Color(0xFF999999))
    }
}

package com.pvpwhgame.hyperoscharge.data

import org.json.JSONObject

data class ChargeStatus(
    val charging: Boolean = false,
    val mode: ChargeMode = ChargeMode.BALANCE,
    val soc: Int = 0,
    val temp: Int = 0,
    val tempTier: Int = 0,
    val socTier: Int = 0,
    val finalTier: Int = 0,
    val state: Int = 0,
    val maxstate: Int = 16,
    val powerDw: Long = 0,
    val ts: Long = 0
) {
    val tempC: Float get() = temp / 10f
    val powerW: Float get() = powerDw / 10f
    val statePercent: Float get() = if (maxstate > 0) state.toFloat() / maxstate else 0f

    companion object {
        fun parse(json: String): ChargeStatus {
            val o = JSONObject(json)
            if (o.optString("error") == "no_battery_cdev") {
                return ChargeStatus()
            }
            return ChargeStatus(
                charging = o.optBoolean("charging", false),
                mode = ChargeMode.fromKey(o.optString("mode", "balance")),
                soc = o.optInt("soc", 0),
                temp = o.optInt("temp", 0),
                tempTier = o.optInt("temp_tier", 0),
                socTier = o.optInt("soc_tier", 0),
                finalTier = o.optInt("final_tier", 0),
                state = o.optInt("state", 0),
                maxstate = o.optInt("maxstate", 16),
                powerDw = o.optLong("power_dw", 0),
                ts = o.optLong("ts", 0)
            )
        }
    }
}

package com.pvpwhgame.hyperoscharge.data

data class HistoryPoint(
    val ts: Long,
    val charging: Int,
    val soc: Int,
    val temp: Int,
    val state: Int,
    val maxstate: Int,
    val mode: String,
    val powerDw: Long
) {
    val tempC: Float get() = temp / 10f
    val powerW: Float get() = powerDw / 10f
    val statePercent: Float get() = if (maxstate > 0) state.toFloat() / maxstate else 0f

    companion object {
        fun parseCsv(text: String): List<HistoryPoint> {
            return text.trim().split("\n")
                .filter { it.isNotBlank() }
                .mapNotNull { line ->
                    val parts = line.split(",")
                    if (parts.size >= 7) {
                        HistoryPoint(
                            ts = parts[0].toLongOrNull() ?: return@mapNotNull null,
                            charging = parts[1].toIntOrNull() ?: 0,
                            soc = parts[2].toIntOrNull() ?: 0,
                            temp = parts[3].toIntOrNull() ?: 0,
                            state = parts[4].toIntOrNull() ?: 0,
                            maxstate = parts[5].toIntOrNull() ?: 16,
                            mode = parts[6],
                            powerDw = parts.getOrNull(7)?.toLongOrNull() ?: 0
                        )
                    } else null
                }
        }
    }
}

